<?php require_once __DIR__.'/alumno_common.php'; $stmt=$pdo->prepare("SELECT m.nombre AS materia,s.fecha,s.estatus,s.observaciones FROM asistencias s JOIN inscripciones i ON i.id=s.inscripcion JOIN materia_profesor mp ON mp.id=i.asignacion JOIN materias m ON m.id=mp.materia WHERE i.alumno=? ORDER BY s.fecha DESC,m.nombre");$stmt->execute([$alumnoActual['id']]);$asistencias=$stmt->fetchAll();$conteo=['asistencia'=>0,'falta'=>0,'retardo'=>0,'justificada'=>0];foreach($asistencias as $a){if(isset($conteo[$a['estatus']]))$conteo[$a['estatus']]++;} alumno_layout('Asistencias','Consulta el registro de asistencia de tus materias','asistenciasAlumno.html',compact('asistencias','conteo'));
